// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Hukuk, vatandaşlık, demokrasi, insan hakları ve Türkiye'nin anayasal düzeni (kolay).
const ozSocialscience4Kolay = <(String, String, List<String>, String)>[
  ('Hukuk kurallarını din, ahlak ve görgü kurallarından ayıran temel özellik aşağıdakilerden hangisidir?', 'Devlet gücüyle desteklenen maddi yaptırıma sahip olması', ['Toplumdaki herkes tarafından benimsenmesi', 'Yazılı olmayan geleneklerden doğması', 'Kişinin yalnızca kendi iç dünyasına ve vicdanına yönelik olması'], 'Hukuk kuralları, uyulmadığında devletin zorlayıcı gücüyle uygulanan maddi yaptırımlara bağlanmıştır. Diğer toplumsal kuralların yaptırımı genellikle manevidir.'),
  ('Selamlaşma, sofrada uyulacak davranışlar ve kılık kıyafete ilişkin yazısız toplumsal kurallara ne ad verilir?', 'Görgü kuralları', ['Ahlak kuralları', 'Hukuk kuralları', 'Örf ve âdet hukuku'], 'Görgü kuralları, insanların gündelik ilişkilerde nazik ve uygun davranmasını düzenler; uyulmaması kınama veya dışlanma gibi manevi tepkilere yol açar.'),
  ('Ahlak kurallarının en belirgin yaptırımı olarak aşağıdakilerden hangisi gösterilir?', 'Vicdan azabı ve toplumun kınaması', ['Mahkemece verilen para cezası', 'İşlemin kesin hükümsüzlüğü', 'Zorla icra yoluyla borcun icra dairesince tahsil edilmesi'], 'Ahlak kuralları kişinin iç dünyasına seslenir; çiğnenmesinin karşılığı vicdan azabı ve toplumsal kınamadır.'),
  ('Hukuk düzeninin kişilere tanıdığı ve hukukça korunan yetkiye ne ad verilir?', 'Hak', ['Borç', 'Yaptırım', 'Fiil'], 'Hak, hukuk düzeninin kişiye tanıdığı ve korumasını sağladığı yetkidir; borç ise bunun karşı tarafında yer alan yükümlülüktür.'),
  ('Hukuk kurallarının genel ve soyut olması ne anlama gelir?', 'Belirli bir kişiye değil, benzer durumdaki herkese uygulanması', ['Yalnızca devlet memurlarını bağlaması', 'Sadece yazılı biçimde bulunabilmesi', 'Uygulanmasının her olayda hâkimin kişisel keyfine bırakılmış olması'], 'Hukuk kuralları belli bir kişi ya da olay için değil, aynı koşuldaki herkes için konur; bu nitelik eşitliğin de güvencesidir.'),
  ('Suç işleyen kişiye hapis veya adli para cezası verilmesi hangi yaptırım türüne örnektir?', 'Ceza', ['Tazminat', 'İptal', 'Cebri icra'], 'Ceza, suç oluşturan fiillere karşı devletin uyguladığı en ağır yaptırım türüdür; hapis ve adli para cezası başlıca örnekleridir.'),
  ('Türk hukukunda normlar hiyerarşisinin en üstünde yer alan hukuk kaynağı hangisidir?', 'Anayasa', ['Kanun', 'Yönetmelik', 'Cumhurbaşkanlığı kararnamesi'], 'Anayasa üstün ve bağlayıcı temel hukuk kuralıdır; kanunlar ve diğer düzenlemeler ona aykırı olamaz.'),
  ('Yazılı hukuk kaynaklarının bulunmadığı durumda uygulanan, toplumda uzun süre tekrarlanarak bağlayıcılık kazanmış kurallara ne ad verilir?', 'Örf ve âdet hukuku', ['Yargı içtihadı', 'Bilimsel görüş', 'Yönetmelik ve genelgeler'], 'Örf ve âdet hukuku, sürekli tekrar ve bağlayıcılık inancıyla oluşan yazısız asli hukuk kaynağıdır.'),
  ('Devletin kendi içindeki örgütlenmesini ve kişilerle olan ilişkilerini egemenlik gücüne dayanarak düzenleyen hukuk dalları topluluğuna ne ad verilir?', 'Kamu hukuku', ['Özel hukuk', 'Borçlar hukuku', 'Ticaret hukuku'], 'Kamu hukukunda devlet, üstün kamu gücüyle taraf olur; anayasa, idare ve ceza hukuku bu grupta yer alır.'),
  ('Türk Medeni Kanunu\'na göre kişilik hangi anda başlar?', 'Çocuğun sağ olarak tamamıyla doğduğu anda', ['Çocuğun nüfusa kaydedildiği anda', 'Çocuğun on sekiz yaşını doldurduğu anda', 'Çocuğa ad konulup nüfus cüzdanı düzenlendiği anda'], 'TMK m.28\'e göre kişilik, çocuğun sağ olarak tamamıyla doğduğu anda başlar ve ölümle sona erer.'),
  ('Türk Medeni Kanunu\'na göre ergin olmanın genel yaşı kaçtır?', '18', ['15', '21', '17'], 'Erginlik on sekiz yaşın doldurulmasıyla başlar; evlenme de kişiyi ergin kılar.'),
  ('Dernekler, vakıflar ve şirketler gibi belli bir amaç için örgütlenmiş ve hukuken kişilik tanınmış topluluklara ne ad verilir?', 'Tüzel kişi', ['Gerçek kişi', 'Kısıtlı kişi', 'Sınırlı ehliyetsiz kişi'], 'Tüzel kişiler, kişi veya mal topluluklarına hukuk düzenince tanınan kişiliktir; kendi adına hak edinip borç altına girebilirler.'),
  ('Bir kişinin ölümüyle malvarlığının kimlere ve nasıl geçeceğini düzenleyen medeni hukuk bölümü hangisidir?', 'Miras hukuku', ['Aile hukuku', 'Eşya hukuku', 'Kişiler hukuku'], 'Miras hukuku, ölen kişinin malvarlığının yasal ve atanmış mirasçılara geçişini düzenler.'),
  ('"Kanunsuz suç ve ceza olmaz" ifadesi hangi ilkeyi anlatır?', 'Suç ve cezada kanunilik ilkesi', ['Kuvvetler ayrılığı ilkesi', 'Yerinden yönetim ilkesi', 'Laiklik ilkesi ve din özgürlüğü'], 'Kanunilik ilkesine göre hangi fiilin suç olduğu ve cezası ancak kanunla belirlenebilir; Anayasa m.38 bunu güvenceye alır.'),
  ('"Suçluluğu hükmen sabit oluncaya kadar kimse suçlu sayılamaz" kuralı hangi ilkenin ifadesidir?', 'Masumiyet karinesi', ['Kanun önünde eşitlik', 'Tabii hâkim ilkesi', 'Kamu yararı ilkesi'], 'Anayasa m.38\'de düzenlenen masumiyet karinesine göre kişi, kesinleşmiş mahkûmiyet kararına kadar suçsuz sayılır.'),
  ('Adli yargı alanında ilk derece ve bölge adliye mahkemelerince verilen kararların son inceleme mercii hangisidir?', 'Yargıtay', ['Danıştay', 'Anayasa Mahkemesi', 'Sayıştay'], 'Yargıtay, adliye mahkemelerince verilen ve kanunun başka bir yargı merciine bırakmadığı kararların son inceleme merciidir (Anayasa m.154).'),
  ('İdari yargının en yüksek mahkemesi hangisidir?', 'Danıştay', ['Yargıtay', 'Uyuşmazlık Mahkemesi', 'Bölge adliye mahkemesi'], 'Danıştay, idare ve vergi mahkemelerince verilen kararların son inceleme merciidir ve aynı zamanda danışma ve inceleme mercii görevi yapar.'),
  ('Seçimlerin başlangıcından bitimine kadar düzen içinde yürütülmesini sağlayan ve kararlarına karşı başka bir mercie başvurulamayan kurum hangisidir?', 'Yüksek Seçim Kurulu', ['Danıştay', 'Anayasa Mahkemesi', 'Sayıştay ve Devlet Denetleme Kurulu'], 'Anayasa m.79\'a göre seçimlerin genel yönetim ve denetimi yargı organlarınca yapılır; YSK kararları aleyhine başka bir mercie başvurulamaz.'),
  ('Hukuk devletinin en temel özelliği hangisidir?', 'Devletin bütün eylemlerinin hukuka bağlı ve yargı denetimine açık olması', ['Yöneticilerin yalnızca kendi vicdanlarına göre karar vermesi', 'Kanunların sadece vatandaşları bağlaması, devleti bağlamaması', 'Mahkemelerin yürütme organına bağlı çalışması'], 'Hukuk devletinde yöneticiler de hukuk kurallarıyla bağlıdır; idarenin her türlü eylem ve işlemi yargı denetimine tabidir.'),
  ('Demokrasi kelimesi hangi dilden gelir ve ne anlama gelir?', 'Yunanca; halkın yönetimi', ['Latince; kralın yönetimi', 'Arapça; danışma meclisi', 'Yunanca; seçkinlerin yönetimi'], 'Demos (halk) ve kratos (yönetim, güç) sözcüklerinden oluşan demokrasi, halkın yönetimi demektir.'),
  ('Vatandaşların kararları meclislerde doğrudan oylayarak aldığı ilk demokrasi uygulamalarından biri hangi şehir devletinde görülmüştür?', 'Atina', ['Sparta', 'Roma', 'Kartaca'], 'MÖ 5. yüzyılda Atina\'da yurttaşlar halk meclisinde (ekklesia) doğrudan oy kullanırdı.'),
  ('Halkın kendi seçtiği temsilciler aracılığıyla yönetime katıldığı demokrasi türüne ne ad verilir?', 'Temsilî demokrasi', ['Doğrudan demokrasi', 'Mutlak monarşi', 'Teokrasi'], 'Modern devletlerde nüfusun büyüklüğü nedeniyle halk egemenliğini seçtiği temsilciler aracılığıyla kullanır.'),
  ('Demokraside farklı görüşlerin, partilerin ve grupların bir arada var olabilmesine ne ad verilir?', 'Çoğulculuk', ['Tekelcilik', 'Merkeziyetçilik', 'Mutlakiyet'], 'Çoğulculuk, toplumdaki farklı düşünce ve çıkarların serbestçe örgütlenip ifade edilebilmesidir.'),
  ('Seçilmiş yöneticilerin yaptıkları işlerin gerekçesini kamuoyuna açıklamak ve sonuçlarından sorumlu tutulmak zorunda olmasına ne ad verilir?', 'Hesap verebilirlik', ['Dokunulmazlık', 'Mutlakiyet', 'Tek partililik ve kuvvetler birliği'], 'Hesap verebilirlik, yöneticilerin halka ve denetim kurumlarına karşı sorumlu olmasıdır; demokratik yönetimin temel unsurlarındandır.'),
  ('Egemenliğin kayıtsız şartsız millete ait olması hangi ilkeyle ifade edilir?', 'Millî egemenlik', ['Kuvvetler birliği', 'Teokrasi', 'Oligarşi'], 'Anayasa m.6\'ya göre egemenlik kayıtsız şartsız Milletindir; hiçbir kişi, zümre veya sınıfa bırakılamaz.'),
  ('Seçmenin oyunu kimseye göstermeden, kapalı kabinde kullanması hangi seçim ilkesinin gereğidir?', 'Gizli oy', ['Eşit oy', 'Tek dereceli seçim', 'Genel oy ilkesi ve açık sayım'], 'Gizli oy ilkesi seçmeni baskıdan korur; oy kapalı kabinde kullanılır ve zarfla sandığa atılır.'),
  ('Her seçmenin oyunun aynı değerde olması ve hiç kimsenin birden fazla oy kullanamaması hangi ilkeyle açıklanır?', 'Eşit oy', ['Gizli oy', 'Serbest seçim', 'Yargı denetimi altında seçim ve sonuçların ilanı'], 'Eşit oy ilkesine göre her seçmenin bir oyu vardır ve oylar eşit değerdedir.'),
  ('Oy kullanma hakkının servet, eğitim ya da cinsiyet gibi koşullara bağlanmadan belli yaşı dolduran tüm vatandaşlara tanınmasına ne ad verilir?', 'Genel oy', ['Sınırlı oy', 'Açık oy', 'Ağırlıklı oy'], 'Genel oy ilkesi, oy hakkının mülk ya da okuryazarlık şartı olmaksızın ergin yurttaşlara tanınmasıdır.'),
  ('Seçmenin oy verirken baskı, tehdit ya da zorlama olmadan kendi iradesiyle karar vermesi hangi ilkenin gereğidir?', 'Serbest seçim', ['Ağırlıklı seçim', 'Çok dereceli seçim', 'Seçimde yaş sınırı ve seçmen kütüğü düzeni'], 'Serbest seçim, seçmenin hiçbir baskı altında kalmadan oyunu kullanabilmesini güvenceye alır.'),
  ('Bir seçim çevresinde en çok oyu alan adayın ya da partinin o çevredeki temsilciliği kazandığı sisteme ne ad verilir?', 'Çoğunluk sistemi', ['Nispi temsil sistemi', 'Karma temsil', 'Kontenjan sistemi ve ulusal liste uygulaması'], 'Çoğunluk sisteminde kazanan, oylardan en fazlasını alandır; diğer oylar temsil edilmez.'),
  ('Bir partinin meclise girebilmesi için ülke genelinde belirli bir oy oranını aşması şartına ne ad verilir?', 'Seçim barajı', ['Seçim çevresi', 'Yasama yılı', 'Oy pusulası'], 'Seçim barajı, ülke genelinde belirli bir oy oranının altında kalan partilerin sandalye dağılımına katılmamasıdır; temsilde adalet ile yönetimde istikrar arasında denge kurma amacı taşır.'),
  ('Başkanlık hükümet sisteminin klasik örneği olarak gösterilen ülke hangisidir?', 'Amerika Birleşik Devletleri', ['Birleşik Krallık', 'Almanya', 'İtalya Cumhuriyeti ve parlamentosu'], 'ABD\'de 1787 Anayasası\'yla kurulan sistemde yürütme, halkın dolaylı seçtiği başkandadır ve yasama ile yürütme sert biçimde ayrılmıştır.'),
  ('Parlamenter sistemin doğduğu ve geliştiği ülke olarak kabul edilen ülke hangisidir?', 'İngiltere', ['ABD', 'İsviçre', 'Fransa ve onun eski sömürgeleri'], 'Parlamenter sistem, İngiltere\'de yüzyıllar içinde kralın yetkilerinin parlamento ve kabine lehine daralmasıyla ortaya çıkmıştır.'),
  ('Kuvvetler ayrılığı ilkesinin temel amacı nedir?', 'İktidarın kötüye kullanılmasını önlemek', ['Devlet harcamalarını azaltmak', 'Seçim sayısını azaltmak', 'Bütün yetkiyi tek bir kurumda toplayarak hızlı karar almak'], 'Yasama, yürütme ve yargının farklı organlarda olması, gücün tek elde toplanmasını ve keyfiliği önler.'),
  ('"Kanunların Ruhu Üzerine" adlı eserinde kuvvetler ayrılığı ilkesini sistemli biçimde ortaya koyan düşünür kimdir?', 'Montesquieu', ['Thomas Hobbes', 'Niccolò Machiavelli', 'Jean Bodin'], 'Montesquieu 1748\'de yayımlanan eserinde özgürlüğün korunması için yasama, yürütme ve yargı güçlerinin ayrı ellerde olmasını savunmuştur.'),
  ('Türkiye Cumhuriyeti Anayasası\'na göre yargı yetkisini Türk Milleti adına kim kullanır?', 'Bağımsız ve tarafsız mahkemeler', ['Cumhurbaşkanı', 'TBMM', 'Bakanlıklar ve valilikler ile kaymakamlıklar'], 'Anayasa m.9\'a göre yargı yetkisi Türk Milleti adına bağımsız ve tarafsız mahkemelerce kullanılır.'),
  ('Tek bir anayasa, tek yasama meclisi ve tek merkezi yönetimin bulunduğu devlet biçimine ne ad verilir?', 'Üniter devlet', ['Federal devlet', 'Konfederasyon', 'Devletler birliği ve gümrük birliği'], 'Üniter devlette siyasal yetki merkezde toplanır; Türkiye üniter bir devlettir.'),
  ('Devlet başkanlığının soydan geçerek el değiştirdiği yönetim biçimine ne ad verilir?', 'Monarşi', ['Cumhuriyet', 'Demokrasi', 'Federasyon'], 'Monarşide hükümdarlık hanedan içinde babadan oğula ya da ailenin bir üyesine geçer.'),
